@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    @* Left Sidebar *@
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        <div class="filter-section">
            <h5>Categories</h5>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="(e) => ToggleCategory(category, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                    </div>
                }
            }
        </div>

        <div class="filter-section">
            <h5>Price Range</h5>
            <div class="price-inputs">
                <input type="number" class="form-control" placeholder="Min" @bind="minPrice" />
                <input type="number" class="form-control" placeholder="Max" @bind="maxPrice" />
            </div>
        </div>

        <div class="filter-section">
            <div class="form-check">
                <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* Main Content *@
    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="loading-state">
                <p>Loading products...</p>
            </div>
        }
        else if (errorMessage is not null)
        {
            <div class="error-state alert alert-danger">
                <p>@errorMessage</p>
                <button class="btn btn-outline-danger" @onclick="LoadProducts">Retry</button>
            </div>
        }
        else if (searchResult is null || searchResult.Items.Count == 0)
        {
            <div class="empty-state">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sortBy">Sort by:</label>
                    <select id="sortBy" class="form-select" @bind="sortBy" @bind:after="LoadProducts">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <div class="results-summary">
                    Showing @(((searchResult.Page - 1) * searchResult.PageSize) + 1)–@(Math.Min(searchResult.Page * searchResult.PageSize, searchResult.TotalCount)) of @searchResult.TotalCount products
                </div>
            </div>

            <div class="product-grid">
                @foreach (var product in searchResult.Items)
                {
                    <ProductCard Product="product"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            @* Pagination *@
            <nav class="pagination-controls" aria-label="Product pagination">
                <button class="btn btn-outline-primary"
                        disabled="@(currentPage <= 1)"
                        @onclick="PreviousPage">
                    Previous
                </button>

                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn @(pageNum == currentPage ? "btn-primary" : "btn-outline-primary")"
                            @onclick="() => GoToPage(pageNum)">
                        @pageNum
                    </button>
                }

                <button class="btn btn-outline-primary"
                        disabled="@(currentPage >= totalPages)"
                        @onclick="NextPage">
                    Next
                </button>
            </nav>
        }
    </main>
</div>

@code {
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalPages;
    private bool isLoading = true;
    private string? errorMessage;
    private PagedResult<Product>? searchResult;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialData();
    }

    private async Task LoadInitialData()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = SearchProducts();

            categories = await categoriesTask;
            searchResult = await productsTask;
            UpdateTotalPages();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task LoadProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            StateHasChanged();

            searchResult = await SearchProducts();
            UpdateTotalPages();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private Task<PagedResult<Product>> SearchProducts()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );

        return ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);
    }

    private void UpdateTotalPages()
    {
        if (searchResult is not null && searchResult.PageSize > 0)
        {
            totalPages = (int)Math.Ceiling((double)searchResult.TotalCount / searchResult.PageSize);
        }
        else
        {
            totalPages = 1;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task PreviousPage()
    {
        if (currentPage > 1)
        {
            currentPage--;
            await LoadProducts();
        }
    }

    private async Task NextPage()
    {
        if (currentPage < totalPages)
        {
            currentPage++;
            await LoadProducts();
        }
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        // Add to cart logic would go here
        await Task.CompletedTask;
    }
}

